VOICE_ADD({"das Merkmal":"","Merkmal":"","Vögel haben gemeinsame Merkmale.":"","das Federkleid":"","Federkleid":"","Alle Vögel haben ein Federkleid.":"","das Ei":"","Ei":"","Alle Vögel legen Eier.":"","die Schuppe":"","Schuppe":"","die Haut":"","Haut":"","die Körpertemperatur":"","Körpertemperatur":"","Die Körpertemperatur der Vögel liegt zwischen 38 °C und 42 °C.":"","die Außentemperatur":"","Außentemperatur":"","Die Körpertemperatur bleibt gleich, auch wenn sich die Außentemperatur ändert.":"","der Strauß":"","Strauß":"","Der Strauß kann nicht fliegen.":"","der Emu":"","Emu":"","Der Emu ist ein flugunfähiger Vogel.":"","der Pinguin":"","Pinguin":"","Der Pinguin kann nicht fliegen, aber gut schwimmen.":"","der Kiwi":"","Kiwi":"","Der Kiwi ist ein flugunfähiger Vogel.":"","gleichwarm":"","Vögel sind, so wie Säugetiere, gleichwarme Wirbeltiere.":"","wechselwarm":"","Reptilien sind wechselwarm, Vögel nicht.":"","flugunfähig":"","Der Strauß, der Emu, der Pinguin und der Kiwi sind flugunfähige Vögel.":"","schwer":"","Flugunfähige Vögel sind zu schwer zum Fliegen.":"","Eier legen":"","speichern":"","Dadurch kann ihr Körper viel mehr Luft speichern.":"","bedecken":"","Das Federkleid bedeckt den ganzen Körper.":"","die Fortpflanzung":"","Fortpflanzung":"","Bei der Fortpflanzung der Vögel findet eine innere Befruchtung statt.":"","die Paarung":"","Paarung":"","Bei der Paarung drücken das Weibchen und das Männchen ihre Kloaken aufeinander.":"","die Samenflüssigkeit":"","Samenflüssigkeit":"","Die Samenflüssigkeit des Männchens fließt in die Kloake des Weibchens.":"","die Samenzelle":"","Samenzelle":"","Der Hahn überträgt seine Samenzellen in den Körper der Henne.":"","die Befruchtung":"","Befruchtung":"","Nach der Befruchtung legt das Weibchen Eier ab.":"","innere Befruchtung":"","Es findet also eine innere Befruchtung statt.":"","die Schale":"","Schale":"","Diese Eier haben eine sehr harte Schale.":"","die Kalkschale":"","Kalkschale":"","Außen hat das Ei eine harte Kalkschale.":"","der Kalk":"","Kalk":"","Die Schale des Eis besteht aus Kalk.":"","die Keimscheibe":"","Keimscheibe":"","Aus der Keimscheibe entwickelt sich der Embryo. Sie liegt immer oben.":""});
